<?php require_once __DIR__.'/../../includes/bootstrap.php';require_role('admin');csrf_check();$id=(int)($_POST['id_kegiatan']??0);$name=trim($_POST['nama_kegiatan']??'');$number=trim($_POST['nomor_kegiatan']??'');$start=$_POST['tanggal_mulai']??'';$end=$_POST['tanggal_selesai']??'';$status=$_POST['status']??'';$target=$_POST['tujuan_akhir']??'';$desc=trim($_POST['deskripsi']??'');if(!$name||!$number||!$start||!$end||$end<$start||!in_array($status,['aktif','nonaktif'],true)||!in_array($target,['lpd','kwitansi','keduanya'],true)){flash('danger','Data kegiatan tidak valid.');redirect('/admin/kegiatan/edit.php?id='.$id);}try{$check=$pdo->prepare('SELECT COUNT(*) FROM progress_harian WHERE id_kegiatan=? AND (tanggal<? OR tanggal>?)');$check->execute([$id,$start,$end]);if((int)$check->fetchColumn()>0){flash('danger','Periode baru tidak boleh mengeluarkan tanggal progress yang sudah tersimpan.');redirect('/admin/kegiatan/edit.php?id='.$id);}$q=$pdo->prepare('UPDATE kegiatan SET nama_kegiatan=?,nomor_kegiatan=?,tanggal_mulai=?,tanggal_selesai=?,status=?,deskripsi=?,tujuan_akhir=? WHERE id_kegiatan=?');$q->execute([$name,$number,$start,$end,$status,$desc?:null,$target,$id]);flash('success','Informasi kegiatan berhasil diperbarui.');}catch(Throwable $e){flash('danger','Perubahan kegiatan gagal disimpan.');}redirect('/admin/kegiatan/detail.php?id='.$id);
